var hasValidPath = function(grid) {
    const m = grid.length;
    const n = grid[0].length;

    // up, right, down, left
    const map = {
        1: [false, true, false, true],
        2: [true, false, true, false],
        3: [false, false, true, true],
        4: [false, true, true, false],
        5: [true, false, false, true],
        6: [true, true, false, false],
    };

    const dfs = (r, c, dir) => {
        if (r < 0 || r >= m || c < 0 || c >= n) {
            return false;
        }
        if (!map[grid[r][c]][dir]) {
            return false;
        }
        if (r === m - 1 && c === n - 1) {
            return true;
        }

        if (dir !== 0 && map[grid[r][c]][0]) return dfs(r - 1, c, 2);
        if (dir !== 1 && map[grid[r][c]][1]) return dfs(r, c + 1, 3);
        if (dir !== 2 && map[grid[r][c]][2]) return dfs(r + 1, c, 0);
        if (dir !== 3 && map[grid[r][c]][3]) return dfs(r, c - 1, 1);

        return false;
    };

    return dfs(0, 0, 0) || dfs(0, 0, 3);
